package vn.edu.hcmute.example3;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.test.web.servlet.MockMvc;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:e3","spring.jpa.hibernate.ddl-auto=create-drop"}) @AutoConfigureMockMvc class Example3ApplicationTests {@Autowired MockMvc mvc; @Test void authPagesPublic()throws Exception{mvc.perform(get("/register")).andExpect(status().isOk());mvc.perform(get("/forgot-password")).andExpect(status().isOk());} @Test void productsRequireLogin()throws Exception{mvc.perform(get("/products")).andExpect(status().is3xxRedirection());} @Test void regularUserCannotManageUsers()throws Exception{mvc.perform(get("/users").with(user("user").roles("USER"))).andExpect(status().isForbidden());} @Test void adminCanOpenUsers()throws Exception{mvc.perform(get("/users").with(user("admin").roles("ADMIN"))).andExpect(status().isOk());}}
